"""INVENTED fixture data for the ML replay demonstration. Nothing here was observed in any market: every price, date and size is generated by a fixed
integer recurrence, every row carries "synthetic": true, the file names start with SYNTHETIC_ and the dates are in 2031 so they cannot be mistaken for recorded
sessions. The folder is written with a manifest in the format the replay runner requires (origin class SYNTHETIC_FIXTURE).

The series is an arbitrary random walk. The call and put premiums are a fixed linear function of the index (a call gains when the index rises, a put when it
falls), so a replay on it can exercise the whole pipeline; what it shows says nothing about any real market and no model can be "good" on it in any meaningful sense.
"""
import json
from dataclasses import dataclass
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal
from pathlib import Path

from ..historical import manifest as mf

IST = timezone(timedelta(hours=5, minutes=30))
SOURCE_ID = "synthetic_ml_demo"
UNDERLYING, EXPIRY, STRIKE = "NIFTY", "2031-05-29", "25000"
CE, PE = f"NIFTY|{EXPIRY}|25000.00|CE", f"NIFTY|{EXPIRY}|25000.00|PE"
FIRST_DAY, BASE_INDEX, SEED = date(2031, 3, 3), Decimal("25000.00"), 20310303
TICK, LOT, HALF_SPREAD = Decimal("0.05"), 65, Decimal("0.10")
DECISION_TIME = (10, 15, 2)          # hour, minute, second (IST) of each day's decision; quotes are stamped 10:15:00, so they are 2 s old


@dataclass(frozen=True)
class SeriesDay:
    day: date
    close: Decimal           # index close of this day (known only after the day ends)
    settle_ce: Decimal       # call settlement of this day
    settle_pe: Decimal
    quote_mid_ce: Decimal    # the 10:15 quote's midpoint: the previous day's settlement
    quote_mid_pe: Decimal


def _tick(value):
    return (value / TICK).quantize(Decimal("1")) * TICK


def premium(close, option_type):
    move = (close - BASE_INDEX) / 2
    return max(Decimal("5.00"), _tick(Decimal("200") + (move if option_type == "CE" else -move)))


def trading_days(count):
    day, out = FIRST_DAY, []
    while len(out) < count:
        if day.weekday() < 5:
            out.append(day)
        day += timedelta(days=1)
    return out


def series(count):
    """`count` days of the invented series, each with the previous day's settlement as that day's 10:15 quote midpoint (the day before the first uses the base)."""
    state, close, days = SEED, BASE_INDEX, []
    previous = (premium(BASE_INDEX, "CE"), premium(BASE_INDEX, "PE"))
    for day in trading_days(count):
        state = (state * 1103515245 + 12345) % 2 ** 31
        basis_points = (state >> 8) % 161 - 80                      # -80 .. +80 basis points
        close = (close * (10000 + basis_points) / 10000).quantize(Decimal("0.01"))
        ce, pe = premium(close, "CE"), premium(close, "PE")
        days.append(SeriesDay(day, close, ce, pe, previous[0], previous[1]))
        previous = (ce, pe)
    return days


def at(day, h, m, s=0):
    return datetime(day.year, day.month, day.day, h, m, s, tzinfo=IST)


def decision_time(day):
    return at(day, *DECISION_TIME)


def _rows(days):
    index, eod, quotes = [], [], []
    for i, d in enumerate(days):
        index.append({"record_kind": "UNDERLYING_EOD", "synthetic": True, "underlying": UNDERLYING, "trading_date": d.day.isoformat(),
                      "open": str(d.close), "high": str(d.close), "low": str(d.close), "close": str(d.close)})
        for option_type, settle, mid, token in (("CE", d.settle_ce, d.quote_mid_ce, "SYN_CE"), ("PE", d.settle_pe, d.quote_mid_pe, "SYN_PE")):
            before = days[i - 1] if i else None
            previous = (before.settle_ce if option_type == "CE" else before.settle_pe) if before else mid
            eod.append({"record_kind": "EOD_CONTRACT_DAY", "synthetic": True, "underlying": UNDERLYING, "expiry": EXPIRY, "strike": STRIKE, "option_type": option_type,
                        "instrument_token": token, "trading_date": d.day.isoformat(), "open": str(settle), "high": str(settle), "low": str(settle), "close": str(settle),
                        "last_price": str(settle), "previous_close": str(previous), "settlement_price": str(settle), "volume": 1000, "volume_unit": "CONTRACTS",
                        "transactions": 100, "open_interest": 5000, "lot_size": LOT})
            stamp = at(d.day, 10, 15).isoformat()
            quotes.append({"record_kind": "QUOTE_SNAPSHOT", "synthetic": True, "underlying": UNDERLYING, "expiry": EXPIRY, "strike": STRIKE, "option_type": option_type,
                           "instrument_token": token, "observed_at": stamp, "available_at": stamp, "time_semantics": "QUOTE_TIME", "bid": str(mid - HALF_SPREAD),
                           "ask": str(mid + HALF_SPREAD), "bid_qty": 650, "ask_qty": 650, "lot_size": LOT, "tick_size": str(TICK)})
    return index, eod, quotes


def _write(folder, name, rows):
    (folder / name).write_bytes("".join(json.dumps(row, sort_keys=True) + "\n" for row in rows).encode("utf-8"))   # bytes: no newline rewriting on Windows


def write_fixture_set(folder, days):
    """Create `folder` (it must not exist) with the invented index closes, contract settlements and 10:15 quotes plus the manifest. Returns the folder."""
    folder = Path(folder)
    folder.mkdir(parents=True)
    index, eod, quotes = _rows(days)
    _write(folder, "SYNTHETIC_index.jsonl", index)
    _write(folder, "SYNTHETIC_eod.jsonl", eod)
    _write(folder, "SYNTHETIC_quotes.jsonl", quotes)
    entries = mf.describe(folder, {"SYNTHETIC_index.jsonl": "UNDERLYING_EOD", "SYNTHETIC_eod.jsonl": "EOD_CONTRACT_DAY", "SYNTHETIC_quotes.jsonl": "QUOTE_SNAPSHOT"},
                          source_id=SOURCE_ID, origin_class="SYNTHETIC_FIXTURE", origin="invented data generated by niftypaper.ml.fixtures, not market data")
    mf.write_manifest(folder / mf.MANIFEST_NAME, entries)
    return folder
